changeSet.sql:
CREATE TABLE organization_financial ( id uuid NOT NULL, tenant_id uuid, branch_id uuid, created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
organization_id uuid NOT NULL, bank_name varchar(255) NOT NULL, account_number varchar(10) NOT NULL, account_name varchar(255) NOT NULL, settlement_currency varchar(3) NOT NULL CHECK (settlement_currency IN ('NGN', 'USD', 'GBP', 'EUR')),
PRIMARY KEY (id) );
COMMENT ON COLUMN organization_financial.account_number IS 'A NUBAN: exactly 10 digits. varchar, not a numeric type — leading zeros are significant and an account number is an identifier, never a quantity.'; COMMENT ON COLUMN organization_financial.account_name IS 'When this doesn''t closely match organizations.registered_name, that''s a compliance red flag worth a reviewer''s attention — but not a blocker (legitimate mismatches exist: trading names, abbreviations, recently renamed companies). No constraint or trigger enforces this; the comparison is a reviewer signal, computed in the verification service in a later slice.';
